function validate([points, k]) {
  if (!Array.isArray(points) || points.length < 2 || points.length > 50) return 'points needs 2 to 50 cells.';
  for (const point of points) {
    if (!Array.isArray(point) || point.length !== 2 || !point.every(Number.isInteger)) return 'Each point is [x, y] with whole numbers.';
    if (point.some(c => c < 1 || c > 100)) return 'Coordinates are between 1 and 100.';
  }
  if (!Number.isInteger(k) || k < 2 || k > points.length) return 'k is between 2 and the number of points.';
  return null;
}

