function minDayskVariants(points, k) {
  const rotated = points.map(([x, y]) => [x + y, x - y]);
  const reachable = (days) => {
    const us = [];
    const vs = [];
    for (const [u, v] of rotated) {
      us.push(u - days, u - days + 1);
      vs.push(v - days, v - days + 1);
    }
    for (const u of us) {
      for (const v of vs) {
        if ((u - v) % 2 !== 0) continue;
        let covered = 0;
        for (const [pu, pv] of rotated) {
          if (Math.abs(pu - u) <= days && Math.abs(pv - v) <= days) covered++;
        }
        if (covered >= k) return true;
      }
    }
    return false;
  };

  let low = 0;
  let high = 200;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (reachable(mid)) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

