function minDayskVariants(points, k) {
  // Try every cell of the bounding box: moving a cell into the box never makes it farther from any variant.
  const xs = points.map(p => p[0]), ys = points.map(p => p[1]);
  let answer = Infinity;
  for (let x = Math.min(...xs); x <= Math.max(...xs); x++) {
    for (let y = Math.min(...ys); y <= Math.max(...ys); y++) {
      const arrival = points.map(([px, py]) => Math.abs(px - x) + Math.abs(py - y)).sort((a, b) => a - b);
      answer = Math.min(answer, arrival[k - 1]);
    }
  }
  return answer;
}

