function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 50 : 2 + Math.floor(rand() * 6);
  const span = large ? 100 : [3, 8, 20, 100][Math.floor(rand() * 4)];
  // Sometimes reuse earlier cells so that several variants start together.
  const points = [];
  for (let i = 0; i < n; i++) {
    if (points.length && rand() < 0.15) {
      points.push([...points[Math.floor(rand() * points.length)]]);
    } else {
      points.push([1 + Math.floor(rand() * span), 1 + Math.floor(rand() * span)]);
    }
  }
  const k = 2 + Math.floor(rand() * (n - 1));
  return [points, k];
}
